impl Document {
    pub(crate) fn compare_area(
        &self,
        _other: &Document,
        a: &Area,
        b: &Area,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_accesskey() != b.get_accesskey() {
            return Err(format!("{path}: ACCESSKEY mismatch"));
        }
        if a.get_alt() != b.get_alt() {
            return Err(format!("{path}: ALT mismatch"));
        }
        if a.get_class_() != b.get_class_() {
            return Err(format!("{path}: CLASS_ mismatch"));
        }
        if a.get_coords() != b.get_coords() {
            return Err(format!("{path}: COORDS mismatch"));
        }
        if a.get_href() != b.get_href() {
            return Err(format!("{path}: HREF mismatch"));
        }
        if a.get_nohref() != b.get_nohref() {
            return Err(format!("{path}: NOHREF mismatch"));
        }
        if a.get_onblur() != b.get_onblur() {
            return Err(format!("{path}: ONBLUR mismatch"));
        }
        if a.get_onclick() != b.get_onclick() {
            return Err(format!("{path}: ONCLICK mismatch"));
        }
        if a.get_ondblclick() != b.get_ondblclick() {
            return Err(format!("{path}: ONDBLCLICK mismatch"));
        }
        if a.get_onfocus() != b.get_onfocus() {
            return Err(format!("{path}: ONFOCUS mismatch"));
        }
        if a.get_onkeydown() != b.get_onkeydown() {
            return Err(format!("{path}: ONKEYDOWN mismatch"));
        }
        if a.get_onkeypress() != b.get_onkeypress() {
            return Err(format!("{path}: ONKEYPRESS mismatch"));
        }
        if a.get_onkeyup() != b.get_onkeyup() {
            return Err(format!("{path}: ONKEYUP mismatch"));
        }
        if a.get_onmousedown() != b.get_onmousedown() {
            return Err(format!("{path}: ONMOUSEDOWN mismatch"));
        }
        if a.get_onmousemove() != b.get_onmousemove() {
            return Err(format!("{path}: ONMOUSEMOVE mismatch"));
        }
        if a.get_onmouseout() != b.get_onmouseout() {
            return Err(format!("{path}: ONMOUSEOUT mismatch"));
        }
        if a.get_onmouseover() != b.get_onmouseover() {
            return Err(format!("{path}: ONMOUSEOVER mismatch"));
        }
        if a.get_onmouseup() != b.get_onmouseup() {
            return Err(format!("{path}: ONMOUSEUP mismatch"));
        }
        if a.get_shape() != b.get_shape() {
            return Err(format!("{path}: SHAPE mismatch"));
        }
        if a.get_style() != b.get_style() {
            return Err(format!("{path}: STYLE mismatch"));
        }
        if a.get_tabindex() != b.get_tabindex() {
            return Err(format!("{path}: TABINDEX mismatch"));
        }
        if a.get_title() != b.get_title() {
            return Err(format!("{path}: TITLE mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_graphic(
        &self,
        other: &Document,
        a: &Graphic,
        b: &Graphic,
        path: &str,
    ) -> Result<(), String> {
        self.compare_engineering_object(other, a.base(), b.base(), path)?;
        if a.get_editfit() != b.get_editfit() {
            return Err(format!("{path}: EDITFIT mismatch"));
        }
        if a.get_edit_height() != b.get_edit_height() {
            return Err(format!("{path}: EDIT_HEIGHT mismatch"));
        }
        if a.get_editscale() != b.get_editscale() {
            return Err(format!("{path}: EDITSCALE mismatch"));
        }
        if a.get_edit_width() != b.get_edit_width() {
            return Err(format!("{path}: EDIT_WIDTH mismatch"));
        }
        if a.get_filename() != b.get_filename() {
            return Err(format!("{path}: FILENAME mismatch"));
        }
        if a.get_fit() != b.get_fit() {
            return Err(format!("{path}: FIT mismatch"));
        }
        if a.get_generator() != b.get_generator() {
            return Err(format!("{path}: GENERATOR mismatch"));
        }
        if a.get_height() != b.get_height() {
            return Err(format!("{path}: HEIGHT mismatch"));
        }
        if a.get_html_fit() != b.get_html_fit() {
            return Err(format!("{path}: HTML_FIT mismatch"));
        }
        if a.get_html_height() != b.get_html_height() {
            return Err(format!("{path}: HTML_HEIGHT mismatch"));
        }
        if a.get_html_scale() != b.get_html_scale() {
            return Err(format!("{path}: HTML_SCALE mismatch"));
        }
        if a.get_html_width() != b.get_html_width() {
            return Err(format!("{path}: HTML_WIDTH mismatch"));
        }
        if a.get_notation() != b.get_notation() {
            return Err(format!("{path}: NOTATION mismatch"));
        }
        if a.get_scale() != b.get_scale() {
            return Err(format!("{path}: SCALE mismatch"));
        }
        if a.get_width() != b.get_width() {
            return Err(format!("{path}: WIDTH mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_l_graphic(
        &self,
        other: &Document,
        a: &LGraphic,
        b: &LGraphic,
        path: &str,
    ) -> Result<(), String> {
        self.compare_language_specific(other, a.base(), b.base(), path)?;
        if a.get_graphic() != b.get_graphic() {
            return Err(format!("{path}: GRAPHIC mismatch"));
        }
        if a.get_map() != b.get_map() {
            return Err(format!("{path}: MAP mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_map(
        &self,
        other: &Document,
        a: &Map,
        b: &Map,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        let list_a = a.get_areas();
        let list_b = b.get_areas();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: AREAS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .areas
                .get(*x)
                .ok_or_else(|| format!("{path}.AREAS[{index}]: id not found in own arena"))?;
            let y = other
                .areas
                .get(*y)
                .ok_or_else(|| format!("{path}.AREAS[{index}]: id not found in other arena"))?;
            self.compare_area(other, x, y, &format!("{path}.AREAS[{index}]"))?;
        }
        if a.get_class_() != b.get_class_() {
            return Err(format!("{path}: CLASS_ mismatch"));
        }
        if a.get_name() != b.get_name() {
            return Err(format!("{path}: NAME mismatch"));
        }
        if a.get_onclick() != b.get_onclick() {
            return Err(format!("{path}: ONCLICK mismatch"));
        }
        if a.get_ondblclick() != b.get_ondblclick() {
            return Err(format!("{path}: ONDBLCLICK mismatch"));
        }
        if a.get_onkeydown() != b.get_onkeydown() {
            return Err(format!("{path}: ONKEYDOWN mismatch"));
        }
        if a.get_onkeypress() != b.get_onkeypress() {
            return Err(format!("{path}: ONKEYPRESS mismatch"));
        }
        if a.get_onkeyup() != b.get_onkeyup() {
            return Err(format!("{path}: ONKEYUP mismatch"));
        }
        if a.get_onmousedown() != b.get_onmousedown() {
            return Err(format!("{path}: ONMOUSEDOWN mismatch"));
        }
        if a.get_onmousemove() != b.get_onmousemove() {
            return Err(format!("{path}: ONMOUSEMOVE mismatch"));
        }
        if a.get_onmouseout() != b.get_onmouseout() {
            return Err(format!("{path}: ONMOUSEOUT mismatch"));
        }
        if a.get_onmouseover() != b.get_onmouseover() {
            return Err(format!("{path}: ONMOUSEOVER mismatch"));
        }
        if a.get_onmouseup() != b.get_onmouseup() {
            return Err(format!("{path}: ONMOUSEUP mismatch"));
        }
        if a.get_title() != b.get_title() {
            return Err(format!("{path}: TITLE mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_ml_figure(
        &self,
        other: &Document,
        a: &MlFigure,
        b: &MlFigure,
        path: &str,
    ) -> Result<(), String> {
        self.compare_paginateable(other, a.base(), b.base(), path)?;
        if a.get_figure_caption() != b.get_figure_caption() {
            return Err(format!("{path}: FIGURE_CAPTION mismatch"));
        }
        if a.get_frame() != b.get_frame() {
            return Err(format!("{path}: FRAME mismatch"));
        }
        if a.get_help_entry() != b.get_help_entry() {
            return Err(format!("{path}: HELP_ENTRY mismatch"));
        }
        let list_a = a.get_l_graphics();
        let list_b = b.get_l_graphics();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: L_GRAPHICS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .l_graphics
                .get(*x)
                .ok_or_else(|| format!("{path}.L_GRAPHICS[{index}]: id not found in own arena"))?;
            let y = other.l_graphics.get(*y).ok_or_else(|| {
                format!("{path}.L_GRAPHICS[{index}]: id not found in other arena")
            })?;
            self.compare_l_graphic(other, x, y, &format!("{path}.L_GRAPHICS[{index}]"))?;
        }
        if a.get_pgwide() != b.get_pgwide() {
            return Err(format!("{path}: PGWIDE mismatch"));
        }
        if a.get_verbatim() != b.get_verbatim() {
            return Err(format!("{path}: VERBATIM mismatch"));
        }
        Ok(())
    }
}
